// Shell — wrap all routes in App.tsx, not per-page
function AppShell({ children }: { children: React.ReactNode }) {
  const navigate = useNavigate();
  const { pathname } = useLocation();
  return (
    <div style={{ display: 'flex', height: '100dvh', overflow: 'hidden' }}>
      <GoabWorkSideMenu
        heading="Service name"
        url="/"
        userName="Staff user"
        primaryContent={
          <>
            <GoabWorkSideMenuItem
              label="Applications"
              url="/applications"
              icon="list"
              current={pathname.startsWith('/applications')}
              onClick={(e: React.MouseEvent) => { e.preventDefault(); navigate('/applications'); }}
            />
            <GoabWorkSideMenuItem
              label="Reviews"
              url="/reviews"
              icon="checkmark-circle"
              current={pathname.startsWith('/reviews')}
              onClick={(e: React.MouseEvent) => { e.preventDefault(); navigate('/reviews'); }}
