        </GoabPageBlock>
      </main>
    </div>
  );
}

// List view page — sequence counter guards against out-of-order responses
const PAGE_SIZE = 10;

export default function ApplicationsView() {
  const [rows, setRows] = useState<Record<string, unknown>[]>([]);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(1);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const loadSeq = useRef(0);

  async function load(p = page) {
    const seq = ++loadSeq.current;
    setLoading(true); setError(null);
    try {
      // Replace with real API call
      const res = await fetch(`/api/v1/applications?page=${p}&limit=${PAGE_SIZE}`);
      if (!res.ok) throw new Error(`Failed to load (${res.status})`);
      const data = await res.json();
      if (seq !== loadSeq.current) return;
      setRows(data.results ?? []);
      setTotal(data.total ?? 0);
    } catch (e) {
      if (seq !== loadSeq.current) return;
      setError(e instanceof Error ? e.message : 'Failed to load.');
    } finally {
      if (seq === loadSeq.current) setLoading(false);
    }
  }

  useEffect(() => { void load(); }, []);

  const STATUS_BADGE: Record<string, 'success' | 'emergency' | 'information' | 'important'> = {
    approved: 'success', declined: 'emergency', 'in-review': 'information', 'action-required': 'important',
  };

  return (
    <div>
      <h1>Applications</h1>
      <goa-spacer vspacing="m" />

      {loading && <div aria-label="Loading"><goa-skeleton type="text" size="4" /></div>}

      {!loading && error && (
        <GoabCallout type="emergency" heading="Unable to load">
          <p>{error}</p>
          <goa-spacer vspacing="s" />
          <GoabButton type="tertiary" onClick={() => load()}>Retry</GoabButton>
        </GoabCallout>
      )}

      {!loading && !error && (
        <>
          <GoabTable version="2" width="100%">
            <thead><tr>
              <th>Reference</th><th>Applicant</th><th>Submitted</th><th>Status</th><th />
            </tr></thead>
            <tbody>
              {rows.map((row) => (
                <tr key={String(row.id)}>
                  <td>{String(row.referenceNumber ?? row.id)}</td>
                  <td>{String(row.applicantName ?? '—')}</td>
                  <td>{row.submittedAt ? new Date(String(row.submittedAt)).toLocaleDateString() : '—'}</td>
                  <td>
                    <GoabBadge
                      type={STATUS_BADGE[String(row.status)] ?? 'information'}
                      content={String(row.status ?? '—')}
                    />
                  </td>
                  <td><GoabButton type="tertiary" size="compact">View</GoabButton></td>
                </tr>
              ))}
            </tbody>
          </GoabTable>

          <goa-spacer vspacing="l" />

          {total > PAGE_SIZE && (
            <GoabPagination
              version="2"
              pageNumber={page}
              itemCount={total}
              perPageCount={PAGE_SIZE}
              onChange={(e: CustomEvent<{ page: number }>) => {
                const next = e.detail?.page ?? 1;
                setPage(next);
                void load(next);
              }}
            />
          )}
        </>
      )}
    </div>
  );
}
